SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.abbr AS oblname, Имена_станций.ordnumb, [Станции_89-2001].YEAR, [Станции_89-2001].NUST, [Станции_89-2001].E, [Станции_89-2001].eotp, [Станции_89-2001].eurt, [Станции_89-2001].eust, [Станции_89-2001].Q, [Станции_89-2001].turt, [Станции_89-2001].tust, [Станции_89-2001].b, [Станции_89-2001].gaz, [Станции_89-2001].mazut, [Станции_89-2001].torf, [Станции_89-2001].slan, [Станции_89-2001].gtt, [Станции_89-2001].proch, [Станции_89-2001].ugol, [Станции_89-2001].don, [Станции_89-2001].podm, [Станции_89-2001].pech, [Доп_угли_99-2001].int, [Доп_угли_99-2001].vork, [Станции_89-2001].arkt, [Станции_89-2001].kuzn, [Станции_89-2001].ural, [Доп_угли_99-2001].sver, [Доп_угли_99-2001].chel, [Доп_угли_99-2001].kizel, [Станции_89-2001].bashk, [Станции_89-2001].ekib, [Станции_89-2001].karag, [Станции_89-2001].kan, [Доп_угли_99-2001].nazar, [Доп_угли_99-2001].ibor, [Доп_угли_99-2001].berez, [Доп_угли_99-2001].per, [Станции_89-2001].irkut, [Доп_угли_99-2001].azey, [Доп_угли_99-2001].cher, [Станции_89-2001].hak, [Станции_89-2001].tuv, [Станции_89-2001].bur, [Доп_угли_99-2001].gusin, [Доп_угли_99-2001].tugn, [Станции_89-2001].chit, [Станции_89-2001].ner, [Станции_89-2001].raich, [Станции_89-2001].urg, [Станции_89-2001].prim, [Станции_89-2001].luch, [Станции_89-2001].mag, [Станции_89-2001].sah, [Станции_89-2001].qotr, [Станции_89-2001].snk, [Станции_89-2001].ewtp, [Станции_89-2001].NT, [Станции_89-2001].obor, [Станции_89-2001].VED, [Станции_89-2001].OBL, [Станции_89-2001].DEP, [Станции_89-2001].OES, [Станции_89-2001].ER, [Станции_89-2001].NUMB1120, IIf([ved]<3,1,2) AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,1,0) AS [sum], Имена_станций.MAIN, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, [Станции_89-2001].ushum, [Доп_угли_99-2001].jer, Knt.Knt
FROM (((([Станции_89-2001] LEFT JOIN [Доп_угли_99-2001] ON ([Станции_89-2001].NUMB1120=[Доп_угли_99-2001].NUMB1120) AND ([Станции_89-2001].YEAR=[Доп_угли_99-2001].YEAR)) INNER JOIN Имена_ОЭС ON ([Станции_89-2001].OES=Имена_ОЭС.oes) AND ([Станции_89-2001].OES=Имена_ОЭС.oes)) INNER JOIN Имена_областей ON [Станции_89-2001].OBL=Имена_областей.OBL) INNER JOIN Имена_станций ON [Станции_89-2001].NUMB1120=Имена_станций.NUMB) LEFT JOIN Knt ON ([Станции_89-2001].NUMB1120=Knt.numb1120) AND ([Станции_89-2001].YEAR=Knt.year);
